package mcpserver

import (
	"context"
	"fmt"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/index"
)

type Server struct {
	idx *index.Index
}

// NewServer creates a new MCP server skeleton.
func NewServer(idx *index.Index) *Server {
	return &Server{idx: idx}
}

// MemoryAskRequest represents the input to the memory.ask tool.
type MemoryAskRequest struct {
	Query string `json:"query"`
}

// MemoryAskResponse represents the output of the memory.ask tool.
type MemoryAskResponse struct {
	Result string `json:"result"`
}

// HandleMemoryAsk implements the memory.ask tool handler.
func (s *Server) HandleMemoryAsk(ctx context.Context, req MemoryAskRequest) (MemoryAskResponse, error) {
	// TODO: Check if there are verified claims to return.
	// Currently there are none, so we immediately fall back to the episode index.

	results, err := s.idx.SearchEpisodes(ctx, req.Query)
	if err != nil {
		return MemoryAskResponse{}, fmt.Errorf("searching episodes: %w", err)
	}

	if len(results) == 0 {
		return MemoryAskResponse{Result: "No results found."}, nil
	}

	var output string
	for i, res := range results {
		output += fmt.Sprintf("Result %d [unverified (episode search)]:\n", i+1)
		output += fmt.Sprintf("Episode ID: %s\n", res.EpisodeID)
		if res.Snippet != "" {
			output += fmt.Sprintf("Match: %s\n", res.Snippet)
		} else {
			output += fmt.Sprintf("Match: %s\n", res.Content)
		}
		output += "\n"
	}

	return MemoryAskResponse{Result: output}, nil
}

package mcpserver_test

import (
	"context"
	"strings"
	"testing"
	"time"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/index"
	"github.com/cblabs-org/repo-memory-plugin/internal/mcpserver"
)

func TestHandleMemoryAsk_FallbackSearch(t *testing.T) {
	// Setup in-memory index
	idx, err := index.NewIndex(":memory:")
	if err != nil {
		t.Fatalf("failed to create in-memory index: %v", err)
	}
	defer idx.Close()

	// Insert test data
	err = idx.InsertEpisode(context.Background(), index.EpisodeRecord{
		EpisodeID: "ep-123",
		SessionID: "sess-1",
		Content:   "This is an important architectural decision about database choice.",
		Date:      time.Now(),
	})
	if err != nil {
		t.Fatalf("failed to insert episode: %v", err)
	}

	srv := mcpserver.NewServer(idx)

	req := mcpserver.MemoryAskRequest{
		Query: "database choice",
	}

	resp, err := srv.HandleMemoryAsk(context.Background(), req)
	if err != nil {
		t.Fatalf("HandleMemoryAsk failed: %v", err)
	}

	if !strings.Contains(resp.Result, "unverified (episode search)") {
		t.Errorf("Expected response to contain 'unverified (episode search)', got: %s", resp.Result)
	}

	if !strings.Contains(resp.Result, "ep-123") {
		t.Errorf("Expected response to contain episode ID 'ep-123', got: %s", resp.Result)
	}
}
